#!/usr/bin/env node
// Break a captured bridge request into its token-weighted sections.
// Usage: node /tmp/analyze-bridge-dump.mjs [/tmp/bridge-dump.json]
import fs from "node:fs";

const path = process.argv[2] || "/tmp/bridge-dump.json";
const raw = fs.readFileSync(path, "utf8");
const req = JSON.parse(raw);
const tok = (s) => Math.round((typeof s === "string" ? s : JSON.stringify(s)).length / 4);

const sys = req.system;
const sysStr = typeof sys === "string" ? sys : JSON.stringify(sys ?? "");
const tools = Array.isArray(req.tools) ? req.tools : [];
const msgs = Array.isArray(req.messages) ? req.messages : [];

console.log("== REQUEST TOTALS ==");
console.log("model:", req.model);
console.log("total payload     ~tok:", tok(raw));
console.log("system prompt     ~tok:", tok(sysStr));
console.log(`tools[] (${tools.length})       ~tok:`, tok(tools));
console.log("messages          ~tok:", tok(msgs));

console.log("\n== TOOLS, largest first (name | ~tok | deferred?) ==");
const rows = tools.map((t) => {
  const name = t.name || "?";
  const hasSchema = t.input_schema && Object.keys(t.input_schema.properties || {}).length > 0;
  // Anthropic defer_loading stub: minimal/empty input_schema + defer flag
  const deferred = t.defer_loading === true || t.type === "deferred" || !hasSchema;
  return { name, t: tok(t), deferred };
}).sort((a, b) => b.t - a.t);
for (const r of rows) {
  console.log(`${String(r.t).padStart(6)}  ${r.deferred ? "stub " : "FULL "} ${r.name}`);
}
const full = rows.filter((r) => !r.deferred);
const stub = rows.filter((r) => r.deferred);
console.log(`\nFULL schemas: ${full.length} (~${full.reduce((a, r) => a + r.t, 0)} tok)`);
console.log(`stub schemas: ${stub.length} (~${stub.reduce((a, r) => a + r.t, 0)} tok)`);

console.log("\n== SYSTEM PROMPT top blocks (split on blank lines, largest 15) ==");
const blocks = sysStr.split(/\n\n+/).map((b, i) => ({ i, t: tok(b), head: b.slice(0, 70).replace(/\n/g, " ") }))
  .sort((a, b) => b.t - a.t).slice(0, 15);
for (const b of blocks) console.log(`${String(b.t).padStart(6)}  ${b.head}`);

