277	// Active recall stays OFF by default, but is opt-in again now that extension.ts
278	// delivers settled recall through the context hook tail and strips stale
279	// active-recall custom messages from provider context.
280	export const DEFAULT_RECALL_CONFIG: RecallConfig = {
281		enabled: false,
282		model_alias: "fast-class",
283		budget_ms: 9_000,
284		ceiling_ms: 15_000,
285		breaker_threshold: 3,
286		breaker_cooldown_ms: 60_000,
287		max_hits: 5,
288		model_override: undefined,
289		show_ui: true,
290		// Agents ask for recall through query, but query is our external hybrid HTTP path.
291		qmd_mode: "query",
292		context_turns: 1,
293		prompt_variant: "terse",
294		min_score: 0,
295		candidate_limit: 80,
296		auto_none_threshold: 0.4,
297		min_prompt_length: 20,
298		qmd_http_port: 8181,
