301	export function recallStateRoot(): string {
302		return process.env.DREAM_EVENTS_HOME ?? join(homedir(), ".dream-memory");
303	}
304	
305	export function recallConfigPath(): string {
306		return join(recallStateRoot(), "recall.toml");
307	}
308	
309	export function recallBreakerPath(): string {
310		return join(recallStateRoot(), "recall-breaker.json");
311	}
312	
313	/**
314	 * Tiny hand-rolled TOML reader. We only need flat key=value pairs in this
315	 * file — no sections, no arrays, no inline tables. Buying a TOML dep for
316	 * this single config is overkill; if the format grows, swap in `@iarna/toml`.
317	 */
318	function parseFlatToml(src: string): Record<string, string> {
319		const out: Record<string, string> = {};
320		for (const raw of src.split(/\r?\n/)) {
321			const line = raw.trim();
322			if (!line || line.startsWith("#")) continue;
323			if (line.startsWith("[")) continue; // section headers ignored
324			const eq = line.indexOf("=");
325			if (eq < 0) continue;
326			const key = line.slice(0, eq).trim();
327			let val = line.slice(eq + 1).trim();
328			// Strip inline comment first: " #" (TOML allows # outside quoted strings).
329			const hash = val.indexOf(" #");
330			if (hash >= 0) val = val.slice(0, hash).trim();
331			const stripOuterQuote = (s: string) => {
332				if (s.length >= 2 && ((s.startsWith('"') && s.endsWith('"')) || (s.startsWith("'") && s.endsWith("'")))) {
333					return s.slice(1, -1);
334				}
335				return s;
336			};
337			val = stripOuterQuote(val);
338			val = stripOuterQuote(val);
339			out[key] = val;
340		}
341		return out;
342	}
343	
344	function asNumber(v: string | undefined, fallback: number): number {
345		if (v === undefined) return fallback;
346		const n = Number(v);
347		return Number.isFinite(n) ? n : fallback;
348	}
349	
350	function envNumber(name: string, fallback: number): number {
351		return asNumber(process.env[name], fallback);
352	}
353	
354	function asBool(v: string | undefined, fallback: boolean): boolean {
355		if (v === undefined) return fallback;
356		return /^(true|1|yes|on)$/i.test(v);
357	}
358	
359	function stripWrappingQuotes(v: string | undefined): string | undefined {
360		if (!v) return v;
361		let out = v;
362		while (
363			out.length >= 2 &&
364			((out.startsWith('"') && out.endsWith('"')) || (out.startsWith("'") && out.endsWith("'")))
365		) {
366			out = out.slice(1, -1);
367		}
368		return out;
369	}
370	
371	/**
372	 * Load recall config from disk:
373	 *   - file at recallConfigPath() provides the persistent override
374	 *   - DREAM_ACTIVE_RECALL=1 forces enabled=true for explicit live opt-in
375	 *   - DREAM_ACTIVE_RECALL=0 forces enabled=false as a kill switch
376	 *   - missing file → DEFAULT_RECALL_CONFIG
377	 */
378	export async function loadRecallConfig(): Promise<RecallConfig> {
379		const path = recallConfigPath();
380		let parsed: Record<string, string> = {};
381		if (existsSync(path)) {
382			try {
383				parsed = parseFlatToml(await readFile(path, "utf8"));
384			} catch {
385				// fall through to defaults
386			}
387		}
388		const cfg: RecallConfig = {
389			enabled: asBool(parsed.enabled, DEFAULT_RECALL_CONFIG.enabled),
390			model_alias: ((parsed.model_alias as RecallConfig["model_alias"]) ??
391				DEFAULT_RECALL_CONFIG.model_alias),
392			budget_ms: asNumber(parsed.budget_ms, DEFAULT_RECALL_CONFIG.budget_ms),
393			ceiling_ms: asNumber(parsed.ceiling_ms, DEFAULT_RECALL_CONFIG.ceiling_ms),
394			breaker_threshold: asNumber(
395				parsed.breaker_threshold,
396				DEFAULT_RECALL_CONFIG.breaker_threshold,
397			),
398			breaker_cooldown_ms: asNumber(
399				parsed.breaker_cooldown_ms,
400				DEFAULT_RECALL_CONFIG.breaker_cooldown_ms,
401			),
402			max_hits: asNumber(parsed.max_hits, DEFAULT_RECALL_CONFIG.max_hits),
403			model_override: parsed.model_override ?? undefined,
404			show_ui: asBool(parsed.show_ui, DEFAULT_RECALL_CONFIG.show_ui),
405			qmd_mode: ((stripWrappingQuotes(parsed.qmd_mode) as RecallConfig["qmd_mode"]) ??
406				DEFAULT_RECALL_CONFIG.qmd_mode),
407			context_turns: asNumber(parsed.context_turns, DEFAULT_RECALL_CONFIG.context_turns),
408			prompt_variant: ((stripWrappingQuotes(parsed.prompt_variant) as RecallConfig["prompt_variant"]) ??
409				DEFAULT_RECALL_CONFIG.prompt_variant),
410			min_score: asNumber(parsed.min_score, DEFAULT_RECALL_CONFIG.min_score),
411			candidate_limit: asNumber(parsed.candidate_limit, DEFAULT_RECALL_CONFIG.candidate_limit),
412			auto_none_threshold: asNumber(parsed.auto_none_threshold, DEFAULT_RECALL_CONFIG.auto_none_threshold),
413			min_prompt_length: asNumber(parsed.min_prompt_length, DEFAULT_RECALL_CONFIG.min_prompt_length),
414			qmd_http_port: asNumber(parsed.qmd_http_port, DEFAULT_RECALL_CONFIG.qmd_http_port),
415		};
416		if (process.env.DREAM_ACTIVE_RECALL === "1") cfg.enabled = true;
417		if (process.env.DREAM_ACTIVE_RECALL === "0") cfg.enabled = false;
418		// Env overrides — autoresearch knobs (Phase 0c + 0d). Each is opt-in;
419		// missing env vars leave the toml/default value in place.
420		if (process.env.RECALL_MAX_HITS) cfg.max_hits = envNumber("RECALL_MAX_HITS", cfg.max_hits);
421		if (process.env.RECALL_BUDGET_MS) cfg.budget_ms = envNumber("RECALL_BUDGET_MS", cfg.budget_ms);
422		if (process.env.RECALL_MODEL_ALIAS) {
423			cfg.model_alias = process.env.RECALL_MODEL_ALIAS as RecallConfig["model_alias"];
424		}
425		if (process.env.RECALL_MODEL_OVERRIDE) cfg.model_override = process.env.RECALL_MODEL_OVERRIDE;
426		if (process.env.RECALL_QMD_MODE) {
427			cfg.qmd_mode = process.env.RECALL_QMD_MODE as RecallConfig["qmd_mode"];
428		}
429		if (process.env.RECALL_CONTEXT_TURNS) cfg.context_turns = envNumber("RECALL_CONTEXT_TURNS", cfg.context_turns);
430		if (process.env.RECALL_PROMPT_VARIANT) {
431			cfg.prompt_variant = process.env.RECALL_PROMPT_VARIANT as RecallConfig["prompt_variant"];
432		}
433		if (process.env.RECALL_MIN_SCORE) cfg.min_score = envNumber("RECALL_MIN_SCORE", cfg.min_score);
434		if (process.env.RECALL_CANDIDATE_LIMIT) {
435			cfg.candidate_limit = envNumber("RECALL_CANDIDATE_LIMIT", cfg.candidate_limit);
436		}
437		if (process.env.RECALL_AUTO_NONE_THRESHOLD) {
438			cfg.auto_none_threshold = envNumber("RECALL_AUTO_NONE_THRESHOLD", cfg.auto_none_threshold);
439		}
440		if (process.env.RECALL_MIN_PROMPT_LENGTH) {
441			cfg.min_prompt_length = envNumber("RECALL_MIN_PROMPT_LENGTH", cfg.min_prompt_length);
442		}
443		if (process.env.DREAM_QMD_HTTP_PORT) {
444			cfg.qmd_http_port = envNumber("DREAM_QMD_HTTP_PORT", cfg.qmd_http_port);
445		}
446		return cfg;
447	}
