449	/** Serialise a RecallConfig as flat TOML — used by `dream recall config`. */
450	export function serialiseRecallConfig(cfg: RecallConfig): string {
451		const lines: string[] = [
452			"# ~/.dream-memory/recall.toml — active-memory v1 config.",
453			"# Per-turn recall sub-agent. Off by default.",
454			"# DREAM_ACTIVE_RECALL=1 enables explicit live opt-in; DREAM_ACTIVE_RECALL=0 remains a kill switch.",
455			"",
456			`enabled = ${cfg.enabled}`,
457			`model_alias = "${cfg.model_alias}"`,
458			`budget_ms = ${cfg.budget_ms}            # default budget for the haiku call`,
459			`ceiling_ms = ${cfg.ceiling_ms}           # hard upper bound, even if budget is bumped at call site`,
460			`breaker_threshold = ${cfg.breaker_threshold}     # consecutive timeouts that open the breaker`,
461			`breaker_cooldown_ms = ${cfg.breaker_cooldown_ms}  # cooldown after open`,
462			`max_hits = ${cfg.max_hits}              # recall top-N pre-fetched and shown to the haiku`,
463		];
464		if (cfg.model_override) {
465			lines.push(`model_override = "${cfg.model_override}"`);
466		}
467		lines.push(`show_ui = ${cfg.show_ui}             # show memory components in the Pi TUI (toggle with /memory)`);
468		lines.push("");
469		// autoresearch-tuned knobs
470		lines.push(`qmd_mode = "${cfg.qmd_mode}"          # "search" = qmd BM25 only, "query" = external hybrid HTTP path`);
471		lines.push(`context_turns = ${cfg.context_turns}            # prepend N prior turns to QMD query (0 = disabled)`);
472		lines.push(`prompt_variant = "${cfg.prompt_variant}"     # terse | compact | expanded | cot`);
473		lines.push(`min_score = ${cfg.min_score}              # discard candidates below this score before haiku (0 = disabled)`);
474		lines.push(`candidate_limit = ${cfg.candidate_limit}        # external hybrid candidate pool size`);
475		lines.push(`auto_none_threshold = ${cfg.auto_none_threshold}       # return NONE without haiku if max hit score < this`);
476		lines.push(`min_prompt_length = ${cfg.min_prompt_length}         # skip recall entirely for prompts shorter than this`);
477		lines.push(`qmd_http_port = ${cfg.qmd_http_port}              # QMD HTTP daemon port (0 = BM25 subprocess only)`);
478		lines.push("");
479		return lines.join("\n");
480	}
