735	/**
736	 * v3 freshness warnings — mirrors Claude Code's `memdir/memoryAge.ts`.
737	 *
738	 * Tag each memory with an age-aware caveat before injection. Stale ≠ wrong,
739	 * but stale file:line citations get asserted as fact too often without one.
740	 *
741	 * Days are floor-rounded; <=1 day = no caveat (fresh enough); >=30 days =
742	 * stronger "historical only" tone. Wording copied verbatim from CC's MIT-
743	 * licensed memoryFreshnessText() for the canonical case.
744	 */
745	export function memoryAgeDays(mtimeMs: number, nowMs: number = Date.now()): number {
746		return Math.max(0, Math.floor((nowMs - mtimeMs) / 86_400_000));
747	}
748	
749	export function freshnessCaveat(days: number): string {
750		if (days <= 1) return "";
751		if (days >= 30) {
752			return (
753				`<system-reminder>This memory is ${days} days old and has not been refreshed since. ` +
754				`Treat as historical only; verify against current code before asserting as fact.</system-reminder>`
755			);
756		}
757		return (
758			`<system-reminder>This memory is ${days} days old. ` +
759			`Memories are point-in-time observations, not live state — ` +
760			`claims about code behavior or file:line citations may be outdated. ` +
761			`Verify against current code before asserting as fact.</system-reminder>`
762		);
763	}
764	
765	/** Best-effort mtime lookup. Returns undefined if path unknown or stat fails. */
766	async function hitMtimeMs(hit: SearchHit): Promise<number | undefined> {
767		if (!hit.file_path) return undefined;
768		try {
769			const s = await stat(hit.file_path);
770			return s.mtimeMs;
771		} catch {
772			return undefined;
773		}
774	}
775	
776	function selectedMemoryBlock(hit: SearchHit, caveat: string): string {
777		const raw = hit.matched_chunk ?? hit.content ?? "";
778		const body = stripFrontmatter(raw).trim().slice(0, 1200);
779		const title = hit.title && hit.title !== hit.permalink ? `Title: ${hit.title}\n` : "";
780		return [caveat, `Memory: ${hit.permalink}`, title ? title.trimEnd() : "", body].filter(Boolean).join("\n");
781	}
782	
783	export interface FreshnessSummary {
784		permalinks: string[];
785		maxAgeDays: number;
786	}
787	
788	export async function buildSelectedRecallContent(
789		hits: SearchHit[],
790		opts: { nowMs?: number; logger?: (m: string) => void } = {},
791	): Promise<{ content: string; freshness: FreshnessSummary }> {
792		const now = opts.nowMs ?? Date.now();
793		const withAges = await Promise.all(
794			hits.map(async (h) => {
795				const m = await hitMtimeMs(h);
796				const days = m === undefined ? 0 : memoryAgeDays(m, now);
797				return { hit: h, days, caveat: freshnessCaveat(days) };
798			}),
799		);
800		const blocks = withAges.map(({ hit, caveat }) => selectedMemoryBlock(hit, caveat));
801		const flagged = withAges.filter((w) => w.caveat.length > 0);
802		const maxAgeDays = withAges.reduce((m, w) => Math.max(m, w.days), 0);
803		if (flagged.length > 0 && opts.logger) {
804			opts.logger(
805				`[active-memory.freshness] permalinks=${flagged.map((w) => w.hit.permalink).join(",")} maxAgeDays=${maxAgeDays}`,
806			);
807		}
808		return {
809			content: `<active-recall>\n${blocks.join("\n\n")}\n</active-recall>`,
810			freshness: { permalinks: flagged.map((w) => w.hit.permalink), maxAgeDays },
811		};
812	}
