863	/**
864	 * Apply temporal decay (mem0-inspired) to recall candidate scores BEFORE the
865	 * curator selects. Stale / never-recalled memories sink in ranking; recently
866	 * recalled ones keep their weight. Usage STATE comes from pi-memory's
867	 * `memory_usage` sidecar — never the cached prefix. Mutates `hits[].score` in
868	 * place. Untracked hits (e.g. dream-memory's own wiki files) get a neutral 1.0
869	 * multiplier. Never throws — decay is best-effort ranking sugar.
870	 */
871	function applyDecayRanking(hits: SearchHit[], log: (m: string) => void, nowMs: number = Date.now()): void {
872		const cfg = loadDecayConfig();
873		if (!cfg.enabled) return;
874		const paths = hits.map((h) => h.file_path).filter((p): p is string => typeof p === "string" && p.length > 0);
875		if (paths.length === 0) return;
876		const sidecar = openPiMemorySidecar();
877		if (!sidecar) return;
878		try {
879			const usage = sidecar.usageByPath(paths);
880			if (usage.size === 0) return;
881			let decayed = 0;
882			for (const hit of hits) {
883				if (!hit.file_path || typeof hit.score !== "number") continue;
884				const w = decayWeightForPath(hit.file_path, usage, { now: nowMs, halfLifeDays: cfg.halfLifeDays });
885				if (w < 1) {
886					hit.score = hit.score * w;
887					decayed++;
888				}
889			}
890			if (decayed > 0) log(`[active-recall] decay applied to ${decayed}/${hits.length} candidates`);
891		} catch (err) {
892			log(`[active-recall] decay ranking skipped: ${(err as Error).message}`);
893		} finally {
894			sidecar.close();
895		}
896	}
897	
898	/**
899	 * Record recall usage for the selected memory paths in pi-memory's `memory_usage`
900	 * sidecar. This increments usage_count + refreshes last_used_at, which is what
901	 * protects a recalled memory from decay-driven auto-delete. Sidecar-only write —
902	 * cache-safe. Never throws.
903	 */
904	function recordRecallUsage(hits: SearchHit[], log: (m: string) => void): void {
905		if (loadDecayConfig().enabled === false) return;
906		const paths = hits.map((h) => h.file_path).filter((p): p is string => typeof p === "string" && p.length > 0);
907		if (paths.length === 0) return;
908		const sidecar = openPiMemorySidecar();
909		if (!sidecar) return;
910		try {
911			sidecar.recordMemoryUsage(paths, randomUUID());
912		} catch (err) {
913			log(`[active-recall] usage record skipped: ${(err as Error).message}`);
914		} finally {
915			sidecar.close();
916		}
917	}
918	
919	/**
920	 * Run a single recall pass. Returns the message-injection or undefined.
921	 * NEVER throws — every failure path collapses to undefined + best-effort
922	 * logging. The user's turn must not be blocked.
923	 */
924	export async function runActiveRecall(
925		opts: ActiveRecallOptions,
926	): Promise<ActiveRecallOutcome | undefined> {
927		const log = opts.logger ?? (() => undefined);
928		const now = opts.nowMs ?? Date.now;
929	
930		let cfg: RecallConfig;
931		try {
932			cfg = opts.config ?? (await loadRecallConfig());
933		} catch (err) {
934			log(`[active-recall] config load failed: ${(err as Error).message}`);
935			return undefined;
936		}
937	
938		if (!cfg.enabled) return undefined;
939	
940		// Sub-agent guard lives at the caller (extension.ts `input` /
941		// `before_agent_start` short-circuit on `ctx.source === "child-agent"`
942		// before they ever schedule recall). The redundant env-var check here
943		// was removed alongside the `PI_MEMORY_SUBAGENT` contract — the CLI
944		// (`dream` subcommand) is intentional ad-hoc invocation and must still
945		// run.
946	
947	
948		// Trim the prompt — empty/whitespace skips.
949		const prompt = opts.prompt.trim();
950		if (prompt.length < 3) return undefined;
951		if (isTrivialRecallPrompt(prompt)) {
952			void emitActiveRecallEvent(opts, { reason: "trivial_prompt", prompt }, "RecallSkipped");
953			return undefined;
954		}
955	
956		// min_prompt_length short-circuit: very short prompts (acknowledgments, single words)
957		// almost never benefit from memory recall. Return NONE deterministically without
958		// touching QMD — faster and avoids false positives on short generic commands.
959		if (cfg.min_prompt_length > 0 && prompt.length < cfg.min_prompt_length && !isLikelyRecallEntityPrompt(prompt)) {
960			log(`[active-recall] min_prompt_length short-circuit: prompt length ${prompt.length} < ${cfg.min_prompt_length}`);
961			void emitActiveRecallEvent(opts, { reason: "min_prompt_length", prompt_length: prompt.length, threshold: cfg.min_prompt_length }, "RecallSkipped");
962			return undefined;
963		}
964	
965		// Build the effective QMD query: when context_turns > 0 and the caller
966		// supplied prior context, prepend it so ambiguous follow-up prompts
967		// ("what was that scar again?") resolve against a richer query signal.
968		// Mirror the bench's buildEffectivePrompt logic: join with ' | ' so qmd's
969		// query parser treats this as a single topic, not a DSL directive.
970		const effectiveQuery =
971			cfg.context_turns > 0 && opts.priorContext && opts.priorContext.trim().length > 0
972				? `${opts.priorContext.trim()} | ${prompt}`
973				: prompt;
974	
975		// Breaker check.
976		const breaker = await readBreakerState();
977		if (isBreakerOpen(breaker, cfg, now())) {
978			log(`[active-recall] breaker OPEN; skip (consecutive_timeouts=${breaker.consecutive_timeouts})`);
979			void getAMTel().then(({ recordCounter }) => recordCounter("dream_memory.active_memory.breaker_opens", 1));
980			void emitActiveRecallEvent(opts, { reason: "breaker_open", consecutive_timeouts: breaker.consecutive_timeouts }, "RecallSkipped");
981			return undefined;
982		}
983	
984		const budgetMs = Math.min(opts.budgetMs ?? cfg.budget_ms, cfg.ceiling_ms);
985		const recallStartedAt = now();
986	
987		// Pre-fetch hits from qmd. qmd may be unhealthy; we federate candidates and
988		// let the selector choose permalinks from actual hits rather than bailing
989		// when hits.length === 0.
990		let qmdHits: SearchHit[] = [];
991		let qmdDegraded = false;
992		let isPrimaryLookupRoute = false;
993		let primaryLookupReason: RecallCollectionRoute["reason"] = "default-memory";
994		try {
995			if (opts.searchFn) {
996				qmdHits = await opts.searchFn(effectiveQuery, { topN: cfg.max_hits, cwd: opts.cwd });
997			} else {
998				const projectSlug = await resolveProjectSlug(opts.cwd ?? process.cwd()).catch(() => undefined);
999				const qmdRoute = resolveActiveRecallRoute(effectiveQuery, projectSlug);
1000				isPrimaryLookupRoute = qmdRoute.reason === "workspace" || qmdRoute.reason === "project-docs";
1001				primaryLookupReason = qmdRoute.reason;
1002				const extras = buildActiveRecallExtraQueries(effectiveQuery);
1003				const baseSearchOpts = {
1004					timeoutMs: budgetMs,
1005					qmdMode: qmdRoute.qmdMode ?? cfg.qmd_mode,
1006					candidateLimit: cfg.candidate_limit,
1007					httpPort: isPrimaryLookupRoute ? 0 : cfg.qmd_http_port,
1008					...(qmdRoute.qmdMode === "search" ? { rerank: false } : {}),
1009					...(extras.length > 0 ? { extraQueries: extras } : {}),
1010				};
1011				const qmdSearch = isPrimaryLookupRoute ? searchMemoryQmd : searchMemory;
1012				const searchCollections = async (collections: string[], pageSize: number) => {
1013					const queries = [effectiveQuery, ...extras];
1014					const { extraQueries: _extraQueries, ...singleQueryOpts } = baseSearchOpts;
1015					const perQuery = await Promise.all(collections.flatMap((collection) =>
1016						queries.map((query) =>
1017							qmdSearch(query, {
1018								...singleQueryOpts,
1019								pageSize,
1020								collections: [collection],
1021							}),
1022						),
1023					));
1024					return {
1025						results: perQuery.flatMap((result) => result.results),
1026						timedOut: perQuery.some((result) => result.timedOut),
1027						error: perQuery.find((result) => result.error)?.error,
1028					};
1029				};
1030				const qmdPromise = qmdRoute.primaryCollections && qmdRoute.globalCollections
1031					? Promise.all([
1032						searchCollections(qmdRoute.primaryCollections, Math.max(3, Math.ceil(cfg.max_hits * 0.6))),
1033						searchCollections(qmdRoute.globalCollections, Math.max(2, Math.floor(cfg.max_hits * 0.4))),
1034					]).then(([primary, global]) => ({
1035						results: [...primary.results, ...global.results],
1036						timedOut: primary.timedOut || global.timedOut,
1037						error: primary.error ?? global.error,
1038					}))
1039					: qmdSearch(effectiveQuery, {
1040						...baseSearchOpts,
1041						pageSize: cfg.max_hits,
1042						collections: qmdRoute.collections,
1043					});
1044				const qmd = await qmdPromise.catch((err) => {
1045					log(`[active-recall] qmd query failed: ${(err as Error).message}`);
1046					return { results: [] as SearchHit[], timedOut: false, error: String(err) };
1047				});
1048				if (qmd.timedOut || qmd.error) {
1049					qmdDegraded = true;
1050					log(`[active-recall] qmd degraded: ${qmd.error ?? "timeout"}`);
1051				}
1052				qmdHits = qmd.results ?? [];
1053			}
1054		} catch (err) {
1055			log(`[active-recall] pre-fetch failed: ${(err as Error).message}`);
1056			// Fall through with empty hits — still let the haiku decide.
1057		}
1058	
1059		// Dedupe by permalink, then optionally filter by cfg.min_score
1060		// (autoresearch knob — 0 disables).
1061		const seen = new Set<string>();
1062		const hits: SearchHit[] = [];
1063		for (const h of qmdHits) {
1064			const key = h.permalink ?? `${h.title}\u0000${h.file_path ?? ""}`;
1065			if (seen.has(key)) continue;
1066			seen.add(key);
1067			if (cfg.min_score > 0 && typeof h.score === "number" && h.score < cfg.min_score) {
1068				continue;
1069			}
1070			hits.push(h);
1071			if (hits.length >= cfg.max_hits) break;
1072		}
1073	
1074		// Short-circuit: if both backends returned nothing, skip the haiku call
1075		// entirely. In practice claude-haiku-4-5 does not reliably output "NONE"
1076		// for empty hits — it hallucinates content from training-data / session
1077		// context instead. Burning 1500+ tokens for a guaranteed no-op is also
1078		// wasteful. The original rationale ("haiku decides what's relevant") only
1079		// holds when there are actual candidates to reason over.
1080		if (hits.length === 0) {
1081			void qmdDegraded;
1082			void emitActiveRecallEvent(opts, { reason: "no_hits" }, "RecallSkipped");
1083			return RECALL_CONSIDERED_EMPTY;
1084		}
1085	
1086		// Temporal decay: down-rank stale / never-recalled candidates BEFORE the
1087		// curator (and before the auto-NONE threshold) sees them. Sidecar-read only;
1088		// mutates hit.score in the dynamic tail — never the cached prefix.
1089		applyDecayRanking(hits, log, now());
1090	
1091		// Auto-NONE short-circuit: if the highest-scoring hit is below the
1092		// configured threshold, the query is almost certainly ambiguous/generic
1093		// and no hit is relevant. Return NONE deterministically without a haiku
1094		// call — decouples ambiguous-NONE detection from stochastic haiku output.
1095		if (cfg.auto_none_threshold > 0 && !isPrimaryLookupRoute) {
1096			const maxScore = Math.max(
1097				...hits.map((h) => (typeof h.score === "number" ? h.score : 0)),
1098			);
1099			if (maxScore < cfg.auto_none_threshold) {
1100				log(
1101					`[active-recall] auto-NONE: max hit score ${maxScore.toFixed(3)} < threshold ${cfg.auto_none_threshold}`,
1102				);
1103				void emitActiveRecallEvent(opts, { reason: "auto_none_threshold", max_score: maxScore, threshold: cfg.auto_none_threshold, hits_fetched: hits.length }, "RecallSkipped");
1104				return RECALL_CONSIDERED_EMPTY;
1105			}
1106		}
1107		void qmdDegraded;
1108	
1109		// Workspace/docs routes are evidence lookups, not preference recall. If QMD
1110		// returned concrete primary hits, inject them directly instead of asking a
1111		// tiny selector model that may prefer topical global meta-memory. This keeps
1112		// lookup prompts deterministic and avoids an extra LLM call.
1113		if (isPrimaryLookupRoute) {
1114			const primaryHits = hits.filter(isPrimaryLookupHit).slice(0, primaryLookupReason === "workspace" ? 2 : 3);
1115			if (primaryHits.length > 0) {
1116				const latency = now() - recallStartedAt;
1117				// Recalled memories gain usage_count — this is what protects them from decay.
1118				recordRecallUsage(primaryHits, log);
1119				const { content } = await buildSelectedRecallContent(primaryHits, { nowMs: now(), logger: log });
1120				void emitActiveRecallEvent(opts, {
1121					result: "selected", model: "qmd-direct", latency_ms: latency,
1122					hits_fetched: hits.length, hits_used: primaryHits.length,
1123					permalinks: primaryHits.map((h) => h.permalink),
1124					bytes: Buffer.byteLength(content, "utf8"),
1125					tokens_in: 0, tokens_out: 0,
1126					qmd: { state: qmdDegraded ? "degraded" : "ok", hits: qmdHits.length },
1127				}, "ActiveRecallSelected");
1128				const summary = content
1129					.replace(/^<active-recall>\n?/, "")
1130					.replace(/\n?<\/active-recall>$/, "")
1131					.replace(/\s+/g, " ")
1132					.trim();
1133				return {
1134					message: {
1135						customType: "dream-memory.active-recall",
1136						content,
1137						display: true,
1138						details: {
1139							hits: primaryHits.length,
1140							latency_ms: latency,
1141							model: "qmd-direct",
1142							summary: summary.length > 320 ? `${summary.slice(0, 317).trimEnd()}…` : summary,
1143							tokens_in: 0,
1144							tokens_out: 0,
1145						},
1146					},
1147				};
1148			}
1149		}
1150	
1151		// Resolve model + auth via the adapter.
1152		let registry: RecallRegistry;
1153		try {
1154			registry =
1155				opts.registry ?? ((await createPiRegistry()).registry as unknown as RecallRegistry);
1156		} catch (err) {
1157			log(`[active-recall] registry construction failed: ${(err as Error).message}`);
1158			return undefined;
1159		}
1160		let model;
1161		try {
1162			model = pickModel(registry, cfg.model_alias, cfg.model_override, opts.parentModel);
1163		} catch (err) {
1164			log(`[active-recall] pickModel failed: ${(err as Error).message}`);
1165			return undefined;
1166		}
1167	
1168		// Wire abort + budget timeout.
1169		const ctrl = new AbortController();
1170		const timeoutHandle = setTimeout(() => ctrl.abort(), budgetMs);
1171		const start = now();
1172	
1173		let _activeRecallResult: ActiveRecallOutcome | undefined;
1174	
1175		const { withSpan, recordLlmCall } = await getAMTel();
1176		await withSpan("active-memory.recall", {
1177			candidates_in: hits.length,
1178			qmd_hits: qmdHits.length,
1179		}, async (span) => {
1180			try {
1181				const systemPromptText = RECALL_PROMPT_VARIANTS[cfg.prompt_variant] ?? RECALL_SYSTEM_PROMPT;
1182				const recallPromptText = buildRecallPrompt(prompt, hits, opts.priorContext);
1183				const result = await callPiModel({
1184					registry,
1185					model,
1186					system: systemPromptText,
1187					prompt: recallPromptText,
1188					maxTokens: 200,
1189					// Recall prompts are per-turn and snippet-heavy; caching them creates writes
1190					// with no reliable future read.
1191					cacheRetention: "none",
1192					signal: ctrl.signal,
1193					...(opts.completeFn ? { completeFn: opts.completeFn } : {}),
1194				});
1195				clearTimeout(timeoutHandle);
1196				await recordBreakerOutcome(breaker, cfg, "success", now());
1197	
1198				const text = result.text.trim();
1199				const latency = now() - start;
1200				const modelId = `${model.provider}/${model.id}`;
1201				log(`[active-recall] ${modelId} ${latency}ms ${result.usage.input}+${result.usage.output} tok ${hits.length} hits`);
1202	
1203				const selectedHits = isNoRelevantRecall(text) ? [] : selectedHitsFromText(text, hits);
1204	
1205				// Opik LLM trace (100% sampling per D5).
1206				void recordLlmCall({
1207					name: "active-memory.recall",
1208					input: recallPromptText,
1209					output: text,
1210					model: modelId,
1211					tokens_in: result.usage.input,
1212					tokens_out: result.usage.output,
1213					...(result.usage.costUsd !== undefined ? { cost_usd: result.usage.costUsd } : {}),
1214					latency_ms: latency,
1215					metadata: {
1216						candidates_in: hits.length,
1217						hits_out: selectedHits.length,
1218						qmd_collections: activeRecallCollections().join(","),
1219						breaker_state: `${breaker.consecutive_timeouts}/${cfg.breaker_threshold}`,
1220					},
1221				});
1222	
1223				if (selectedHits.length === 0) {
1224					span.setAttributes({ hits_out: 0, result: "none" });
1225					void emitActiveRecallEvent(opts, {
1226						result: "none", model: modelId, latency_ms: latency,
1227						hits_fetched: hits.length, hits_used: 0, bytes: 0,
1228						tokens_in: result.usage.input, tokens_out: result.usage.output,
1229						qmd: { state: qmdDegraded ? "degraded" : "ok", hits: qmdHits.length },
1230					}, "ActiveRecallSelected");
1231					_activeRecallResult = RECALL_CONSIDERED_EMPTY;
1232					return;
1233				}
1234	
1235				// Recalled memories gain usage_count — this is what protects them from decay.
1236				recordRecallUsage(selectedHits, log);
1237				const { content, freshness } = await buildSelectedRecallContent(selectedHits, { nowMs: now(), logger: log });
1238				void freshness;
1239				span.setAttributes({ hits_out: selectedHits.length, result: "selected", bytes: Buffer.byteLength(content, "utf8") });
1240				void emitActiveRecallEvent(opts, {
1241					result: "selected", model: modelId, latency_ms: latency,
1242					hits_fetched: hits.length, hits_used: selectedHits.length,
1243					permalinks: selectedHits.map((h) => h.permalink),
1244					bytes: Buffer.byteLength(content, "utf8"),
1245					tokens_in: result.usage.input, tokens_out: result.usage.output,
1246					qmd: { state: qmdDegraded ? "degraded" : "ok", hits: qmdHits.length },
1247				}, "ActiveRecallSelected");
1248	
1249				const summary = content
1250					.replace(/^<active-recall>\n?/, "")
1251					.replace(/\n?<\/active-recall>$/, "")
1252					.replace(/\s+/g, " ")
1253					.trim();
1254	
1255				_activeRecallResult = {
1256					message: {
1257						customType: "dream-memory.active-recall",
1258						content,
1259						display: true,
1260						details: {
1261							hits: selectedHits.length,
1262							latency_ms: latency,
1263							model: modelId,
1264							summary: summary.length > 320 ? `${summary.slice(0, 317).trimEnd()}…` : summary,
1265							tokens_in: result.usage.input,
1266							tokens_out: result.usage.output,
1267							...(result.usage.costUsd !== undefined ? { cost_usd: result.usage.costUsd } : {}),
1268						},
1269					},
1270				};
1271			} catch (err) {
1272				clearTimeout(timeoutHandle);
1273				const isTimeout = err instanceof PiModelAbortError;
1274				const latency = now() - start;
1275				if (isTimeout) {
1276					await recordBreakerOutcome(breaker, cfg, "timeout", now());
1277					void getAMTel().then(({ recordCounter }) => recordCounter("dream_memory.active_memory.breaker_opens", 1));
1278					log(`[active-recall] timeout @${budgetMs}ms; breaker now ${breaker.consecutive_timeouts + 1}/${cfg.breaker_threshold}`);
1279					span.setAttributes({ result: "timeout" });
1280					void emitActiveRecallEvent(opts, {
1281						result: "timeout", model: `${model.provider}/${model.id}`, latency_ms: latency,
1282						hits_fetched: hits.length, hits_used: 0, bytes: 0,
1283						tokens_in: 0, tokens_out: 0,
1284						qmd: { state: "ok", hits: qmdHits.length },
1285					});
1286				} else if (err instanceof PiModelAuthError || err instanceof PiModelError) {
1287					log(`[active-recall] ${err.name}: ${err.message}`);
1288				} else {
1289					log(`[active-recall] unexpected: ${(err as Error).message}`);
1290				}
1291				_activeRecallResult = undefined;
1292			}
1293		});
1294	
1295		return _activeRecallResult;
1296	}
1297	
1298	async function emitActiveRecallEvent(
1299		opts: Pick<ActiveRecallOptions, "sessionId" | "client" | "cwd">,
1300		payload: Record<string, unknown>,
1301		eventType: "ActiveRecallSelected" | "ActiveRecallInjected" | "RecallSkipped" = "ActiveRecallInjected",
1302	): Promise<void> {
1303		if (!opts.sessionId) return;
1304		try {
1305			const slug = await resolveProjectSlug(opts.cwd);
1306			await appendEvent({
1307				sessionId: opts.sessionId,
1308				client: opts.client ?? "pi",
1309				cwd: opts.cwd,
1310				projectSlug: slug,
1311				eventType,
1312				payload,
1313			});
1314		} catch {
1315			/* never throw from instrumentation */
1316		}
1317	}
