node --input-type=module -e '
import fs from "node:fs";
const req = JSON.parse(fs.readFileSync("/tmp/bridge-dump.json","utf8"));
const tok = s => Math.round((typeof s==="string"?s:JSON.stringify(s)).length/4);
const msgs = req.messages || [];
const out = [];
out.push(`messages: ${msgs.length}, total msg tok ~${tok(msgs)}`);
out.push(`system field tok ~${tok(req.system)}  (type=${Array.isArray(req.system)?"array["+req.system.length+"]":typeof req.system})`);
out.push("");
// Per-message, per-block breakdown
const blocks = [];
msgs.forEach((m,mi) => {
  const c = m.content;
  if (typeof c === "string") { blocks.push({mi, role:m.role, type:"string", tok:tok(c), head:c.slice(0,160).replace(/\n/g," ")}); return; }
  if (Array.isArray(c)) c.forEach((b,bi) => {
    let head="";
    if (b.type==="text") head=(b.text||"").slice(0,160);
    else if (b.type==="tool_result") head="["+(typeof b.content==="string"?b.content:JSON.stringify(b.content)).slice(0,150)+"]";
    else if (b.type==="tool_use") head=b.name+" "+JSON.stringify(b.input||"").slice(0,100);
    else head=JSON.stringify(b).slice(0,150);
    blocks.push({mi, role:m.role, type:b.type, tok:tok(b), head:head.replace(/\n/g," ")});
  });
});
out.push("=== TOP 25 BLOCKS BY SIZE ===");
blocks.sort((a,b)=>b.tok-a.tok).slice(0,25).forEach(b=>{
  out.push(`${String(b.tok).padStart(6)} tok  msg#${b.mi} ${b.role}/${b.type}  ${b.head}`);
});
out.push("");
out.push("=== cache_control breakpoints (where are they?) ===");
msgs.forEach((m,mi)=>{
  const c=m.content;
  if(Array.isArray(c)) c.forEach((b,bi)=>{ if(b.cache_control) out.push(`msg#${mi} block#${bi} ${b.type} cache_control=${JSON.stringify(b.cache_control)} tok~${tok(b)}`); });
});
fs.writeFileSync("/tmp/burst-blocks.txt", out.join("\n"));
console.log("wrote /tmp/burst-blocks.txt");
'

