const est = (s) => Math.ceil((typeof s === "string" ? s.length : JSON.stringify(s).length) / 4);
const rows = [];
let total = 0;
msgs.forEach((m, i) => {
  const blocks = Array.isArray(m.content) ? m.content : [{ type: "text", text: m.content }];
  blocks.forEach((b, j) => {
    let t = 0, kind = b.type || "?", preview = "";
    if (b.type === "text") { t = est(b.text); preview = (b.text || "").slice(0, 90); }
    else if (b.type === "thinking") { t = est(b.thinking || ""); preview = "THINKING " + (b.thinking || "").slice(0, 70); }
    else if (b.type === "tool_use") { t = est(b); preview = "tool_use " + (b.name || "") + " " + JSON.stringify(b.input || {}).slice(0, 60); }
    else if (b.type === "tool_result") {
      const c = b.content;
      const txt = Array.isArray(c) ? c.map(x => x.text || JSON.stringify(x)).join("") : (typeof c === "string" ? c : JSON.stringify(c));
      t = est(txt); preview = "tool_result " + txt.slice(0, 80);
    } else { t = est(b); preview = JSON.stringify(b).slice(0, 80); }
    total += t;
    const cc = b.cache_control ? ` [CC ${b.cache_control.ttl || b.cache_control.type}]` : "";
    rows.push({ i, j, role: m.role, kind, t, preview: preview.replace(/\n/g, " "), cc });
  });
});
