node -e '
const fs=require("fs");
const f=process.env.HOME+"/.pi/agent/logs/claude-bridge.err.log";
const lines=fs.readFileSync(f,"utf8").split("\n");
let cur=null; const breaks=[];
for(const l of lines){
  let m=l.match(/\[CACHE-BREAK\] (\S+?): cache_read ([\d,]+) -> ([\d,]+) \(drop ([\d,]+), write ([\d,]+)\)/);
  if(m){ cur={sess:m[1],read:+m[2].replace(/,/g,""),after:+m[3].replace(/,/g,""),drop:+m[4].replace(/,/g,""),write:+m[5].replace(/,/g,""),firstDiv:null,toolChange:false}; breaks.push(cur); continue; }
  let d=l.match(/first divergence: msg\[(\d+)\] of (\d+) shared/);
  if(d&&cur&&cur.firstDiv===null){ cur.firstDiv=+d[1]; cur.shared=+d[2]; }
  if(/tools (added|removed)/.test(l)&&cur) cur.toolChange=true;
  if(/history truncated/.test(l)&&cur) cur.truncated=true;
}
// aggregate
const bySess={};
let totWaste=0;
for(const b of breaks){
  const s=b.sess.replace(/^pi:/,"").slice(0,13);
  bySess[s]=bySess[s]||{n:0,write:0,div0:0,divDeep:0,toolCh:0};
  bySess[s].n++; bySess[s].write+=b.write; totWaste+=b.write;
  if(b.firstDiv===0) bySess[s].div0++; else if(b.firstDiv!==null) bySess[s].divDeep++;
  if(b.toolChange) bySess[s].toolCh++;
}
console.log("TOTAL cache-breaks:",breaks.length,"| total wasted write tokens:",totWaste.toLocaleString());
console.log("\nper session (busts | wasted-write | div@0 | div@deep | tool-change-busts):");
Object.entries(bySess).sort((a,b)=>b[1].write-a[1].write).forEach(([s,v])=>
  console.log(" ",s,"|",String(v.n).padStart(3),"|",String(v.write.toLocaleString()).padStart(11),"|",String(v.div0).padStart(3),"|",String(v.divDeep).padStart(3),"|",v.toolCh));
// biggest single busts
console.log("\nTop 8 single busts by write:");
breaks.sort((a,b)=>b.write-a.write).slice(0,8).forEach(b=>console.log("  write",b.write.toLocaleString().padStart(8),"firstDiv@",b.firstDiv,"shared",b.shared,b.toolChange?"[TOOLCH]":"",b.truncated?"[TRUNC]":"",b.sess.slice(0,16)));
' 2>&1 | head -50

