1	// CACHE CRITICAL regression test.
2	//
3	// The provider-context rewrite path (`applyQueuedGoalProviderContextRewrites`)
4	// mutates an in-place historical message every onContext event so the agent
5	// sees the current continuation prompt at a fixed message position. Anthropic
6	// prompt cache invalidates from the first byte mutation onward; any volatile
7	// field in the rewrite (elapsed time, tokens used, tokens remaining) drops
8	// cache_read to the system+tools anchor and forces a full transcript rewrite
9	// every turn.
10	//
11	// Bug history: pre-fix, the rewrite called `continuationPrompt(goal)` /
12	// `compactContinuationPrompt(goal)` which both render a Budget block whose
13	// numbers change every turn. Bridge logs showed `CACHE-SILENT-BUST` with
14	// `messages mutated at position(s) 2` on every turn of every goal-active
15	// session — most visibly the openclaw `Pursuing goal (11m)` session at
16	// ~51% hit rate / 2M cacheWrite over 57 turns.
17	//
18	// Fix: rewrite path now calls `continuationPromptStable` /
19	// `compactContinuationPromptStable`, both stripped of volatile fields. Live
20	// numbers remain accessible to the agent via the get_goal tool.
21	//
22	// This test asserts the property the bug violated: byte-identical rewrite
23	// output for two goal snapshots that differ only in volatile usage fields.
24	// If this test fails, the cache-burn regression is back.
25	
26	import assert from "node:assert/strict";
27	import { existsSync, readFileSync, rmSync } from "node:fs";
28	import { join } from "node:path";
29	import { test } from "node:test";
30	
31	import {
32	  applyQueuedGoalProviderContextRewrites,
33	  extensionQueuedGoalWorkMessageIdForRuntime,
34	} from "../src/queued-goal-work.js";
35	import {
36	  compactContinuationPromptStable,
37	  continuationGoalIdFromPrompt,
38	  continuationPromptStable,
39	} from "../src/prompts.js";
40	import type { ThreadGoal } from "../src/types.js";
41	import {
42	  goalCustomContextMessage,
43	  goalUserContextMessage,
44	} from "./support/runtime-harness.js";
45	
46	const baseGoal: ThreadGoal = {
47	  goalId: "goal-cache-stable-1",
48	  objective: "find the cache bust culprit, diagnose, verify, and fix",
49	  status: "active",
50	  tokenBudget: null,
51	  usage: { tokensUsed: 0, activeSeconds: 0 },
52	  createdAt: 0,
53	  updatedAt: 0,
54	};
55	
56	const resolveStaleQueuedGoalWorkMessageId = (
57	  message: Parameters<typeof extensionQueuedGoalWorkMessageIdForRuntime>[0],
58	) => extensionQueuedGoalWorkMessageIdForRuntime(message, continuationGoalIdFromPrompt);
59	
60	const resolveActiveContinuationQueuedGoalWorkMessageId =
61	  resolveStaleQueuedGoalWorkMessageId;
62	
63	function withUsage(
64	  goal: ThreadGoal,
65	  usage: { tokensUsed: number; activeSeconds: number },
66	): ThreadGoal {
67	  return { ...goal, usage };
68	}
69	
70	function rewriteFor(goal: ThreadGoal): string {
71	  const message = goalCustomContextMessage({
72	    content: continuationPromptStable(goal),
73	    details: { kind: "command_start", goalId: goal.goalId },
74	    timestamp: 1,
75	  });
76	  const { messages } = applyQueuedGoalProviderContextRewrites([message], {
77	    goal,
78	    resolveStaleQueuedGoalWorkMessageId,
79	    resolveActiveContinuationQueuedGoalWorkMessageId,
80	  });
81	  return String(messages[0]?.content ?? "");
82	}
83	
84	function rewriteCompactFor(goal: ThreadGoal): string {
85	  const message = goalCustomContextMessage({
86	    content: compactContinuationPromptStable(goal),
87	    details: { kind: "continuation", goalId: goal.goalId },
88	    timestamp: 1,
89	  });
90	  const { messages } = applyQueuedGoalProviderContextRewrites([message], {
91	    goal,
92	    resolveStaleQueuedGoalWorkMessageId,
93	    resolveActiveContinuationQueuedGoalWorkMessageId,
94	  });
95	  return String(messages[0]?.content ?? "");
96	}
