import { readFileSync } from "node:fs";
const p = process.argv[2] || "/tmp/bridge-dump.json";
const body = JSON.parse(readFileSync(p, "utf8"));
const msgs = body.messages || [];
const est = (s) => Math.ceil((typeof s === "string" ? s : JSON.stringify(s ?? "")).length / 4);
// 1) thinking signature totals
let thinkCount = 0, thinkTok = 0, sigTok = 0, sigChars = 0;
let tjPlaceholders = [];
let toolResultFull = 0, toolResultCount = 0;
msgs.forEach((m, i) => {
  const blocks = Array.isArray(m.content) ? m.content : [];
  blocks.forEach((b) => {
    if (b.type === "thinking") { thinkCount++; thinkTok += est(b.thinking || ""); if (b.signature){ sigTok += est(b.signature); sigChars += b.signature.length; } }
    if (b.type === "tool_result") {
      toolResultCount++;
      const c = b.content;
      const txt = Array.isArray(c) ? c.map(x => x.text || "").join("") : (typeof c === "string" ? c : JSON.stringify(c));
      toolResultFull += est(txt);
      if (/tokenjuice compacted|deterministically compacted|tj_[0-9a-f]/.test(txt)) tjPlaceholders.push({ i, tok: est(txt), head: txt.slice(0, 70).replace(/\n/g," ") });
    }
  });
});
console.log("messages:", msgs.length);
console.log("thinking blocks:", thinkCount, "| thinking content tok~", thinkTok, "| signature tok~", sigTok, "| signature chars", sigChars, "| avg sig chars", Math.round(sigChars/Math.max(1,thinkCount)));
console.log("tool_result blocks:", toolResultCount, "| total tok~", toolResultFull);
console.log("tokenjuice placeholders in history:", tjPlaceholders.length);
tjPlaceholders.slice(0,12).forEach(x => console.log("  msg#"+x.i, x.tok+"tok", x.head));
// 2) cache_control breakpoints
console.log("\ncache_control breakpoints:");
msgs.forEach((m,i)=>{ const bs=Array.isArray(m.content)?m.content:[]; bs.forEach((b,j)=>{ if(b.cache_control) console.log("  msg#"+i,"blk#"+j,m.role,b.type,JSON.stringify(b.cache_control)); }); });
// 3) is there a system field?
console.log("\nsystem field tok~", est(body.system), "| top-level keys:", Object.keys(body).join(","));

