  const harness = createRuntimeHarness();
  await harness.runCommand("ship it");
  const goal = harness.snapshot().goal;
  assert.ok(goal);

  const fullStart = continuationPrompt(goal);
  const olderContinuation = continuationPrompt({
    ...goal,
    usage: { ...goal.usage, tokensUsed: 1, activeSeconds: 1 },
  });
  const latestContinuation = compactContinuationPrompt({
    ...goal,
    usage: { ...goal.usage, tokensUsed: 99, activeSeconds: 42 },
  });

  const messages = [
    goalCustomContextMessage({
      content: fullStart,
      details: { kind: "command_start", goalId: goal.goalId },
      timestamp: 1,
    }),
    goalCustomContextMessage({
      content: olderContinuation,
      details: { kind: "continuation", goalId: goal.goalId },
      timestamp: 2,
    }),
    goalCustomContextMessage({
      content: latestContinuation,
      details: { kind: "continuation", goalId: goal.goalId },
      timestamp: 3,
    }),
  ];

  const results = await emitProviderContext(harness, messages);
  const result = requireProviderContextResult(results);
  assert.equal(result.messages.length, 3);

  // CACHE CRITICAL: earlier continuations for the active goal MUST keep their
  // exact bytes and details. Supersession is positional — each block carries
  // CONTINUATION_SUPERSEDE_NOTICE, so a later block authoritatively supersedes
  // earlier ones without any in-place rewrite. Mutating a historical message
  // here (e.g. into a "superseded" stub) would invalidate the Anthropic prompt
  // cache from that position to the tail.
  assert.equal(providerContextMessageAt(result, 0).content, fullStart);
  assert.deepEqual(providerContextMessageAt(result, 0).details, {
    kind: "command_start",
    goalId: goal.goalId,
  });
  assert.equal(providerContextMessageAt(result, 1).content, olderContinuation);
  assert.deepEqual(providerContextMessageAt(result, 1).details, {
    kind: "continuation",
    goalId: goal.goalId,
  });

  const latestContent = String(providerContextMessageAt(result, 2).content);

