// CACHE CRITICAL regression test.
//
// The provider-context rewrite path (`applyQueuedGoalProviderContextRewrites`)
// mutates an in-place historical message every onContext event so the agent
// sees the current continuation prompt at a fixed message position. Anthropic
// prompt cache invalidates from the first byte mutation onward; any volatile
// field in the rewrite (elapsed time, tokens used, tokens remaining) drops
// cache_read to the system+tools anchor and forces a full transcript rewrite
// every turn.
//
// Bug history: pre-fix, the rewrite called `continuationPrompt(goal)` /
// `compactContinuationPrompt(goal)` which both render a Budget block whose
// numbers change every turn. Bridge logs showed `CACHE-SILENT-BUST` with
// `messages mutated at position(s) 2` on every turn of every goal-active
// session — most visibly the openclaw `Pursuing goal (11m)` session at
// ~51% hit rate / 2M cacheWrite over 57 turns.
//
// Fix: rewrite path now calls `continuationPromptStable` /
// `compactContinuationPromptStable`, both stripped of volatile fields. Live
// numbers remain accessible to the agent via the get_goal tool.
//
// This test asserts the property the bug violated: byte-identical rewrite
// output for two goal snapshots that differ only in volatile usage fields.
// If this test fails, the cache-burn regression is back.

import assert from "node:assert/strict";
import { existsSync, readFileSync, rmSync } from "node:fs";
import { join } from "node:path";
import { test } from "node:test";

import {
  applyQueuedGoalProviderContextRewrites,
  extensionQueuedGoalWorkMessageIdForRuntime,
} from "../src/queued-goal-work.js";
import {
  compactContinuationPromptStable,
  continuationGoalIdFromPrompt,
  continuationPromptStable,
} from "../src/prompts.js";
import type { ThreadGoal } from "../src/types.js";
import {
  goalCustomContextMessage,
  goalUserContextMessage,
} from "./support/runtime-harness.js";

const baseGoal: ThreadGoal = {
  goalId: "goal-cache-stable-1",
  objective: "find the cache bust culprit, diagnose, verify, and fix",
  status: "active",
  tokenBudget: null,
  usage: { tokensUsed: 0, activeSeconds: 0 },
  createdAt: 0,
  updatedAt: 0,
};

const resolveStaleQueuedGoalWorkMessageId = (
  message: Parameters<typeof extensionQueuedGoalWorkMessageIdForRuntime>[0],
) => extensionQueuedGoalWorkMessageIdForRuntime(message, continuationGoalIdFromPrompt);

const resolveActiveContinuationQueuedGoalWorkMessageId =
  resolveStaleQueuedGoalWorkMessageId;

function withUsage(
  goal: ThreadGoal,
  usage: { tokensUsed: number; activeSeconds: number },
): ThreadGoal {
  return { ...goal, usage };
}

function rewriteFor(goal: ThreadGoal): string {
  const message = goalCustomContextMessage({
    content: continuationPromptStable(goal),
    details: { kind: "command_start", goalId: goal.goalId },
    timestamp: 1,
  });
  const { messages } = applyQueuedGoalProviderContextRewrites([message], {
    goal,
    resolveStaleQueuedGoalWorkMessageId,
    resolveActiveContinuationQueuedGoalWorkMessageId,
  });
  return String(messages[0]?.content ?? "");
}

function rewriteCompactFor(goal: ThreadGoal): string {
  const message = goalCustomContextMessage({
    content: compactContinuationPromptStable(goal),
    details: { kind: "continuation", goalId: goal.goalId },
    timestamp: 1,
  });
  const { messages } = applyQueuedGoalProviderContextRewrites([message], {
    goal,
    resolveStaleQueuedGoalWorkMessageId,
    resolveActiveContinuationQueuedGoalWorkMessageId,
  });
  return String(messages[0]?.content ?? "");
}

test("continuationPromptStable is byte-identical across volatile usage diffs", () => {
  const a = continuationPromptStable(withUsage(baseGoal, { tokensUsed: 0, activeSeconds: 0 }));
  const b = continuationPromptStable(withUsage(baseGoal, { tokensUsed: 12_558, activeSeconds: 61 }));
  const c = continuationPromptStable(withUsage(baseGoal, { tokensUsed: 21_059, activeSeconds: 300 }));
  assert.equal(a, b, "tokensUsed/activeSeconds must not affect rewrite bytes");
  assert.equal(b, c, "tokensUsed/activeSeconds must not affect rewrite bytes");
  // Defensive: ensure the volatile labels are absent from the body.
  assert.doesNotMatch(a, /Tokens used:/);
  assert.doesNotMatch(a, /Time spent pursuing goal:/);
  assert.doesNotMatch(a, /Tokens remaining:/);
});

test("compactContinuationPromptStable is byte-identical across volatile usage diffs", () => {
  const a = compactContinuationPromptStable(withUsage(baseGoal, { tokensUsed: 0, activeSeconds: 0 }));
  const b = compactContinuationPromptStable(withUsage(baseGoal, { tokensUsed: 99, activeSeconds: 42 }));
  const c = compactContinuationPromptStable(withUsage(baseGoal, { tokensUsed: 999_999, activeSeconds: 86_400 }));
  assert.equal(a, b);
  assert.equal(b, c);
  assert.doesNotMatch(a, /Tokens used:/);
  assert.doesNotMatch(a, /Time spent pursuing goal:/);
});

